def T(id, title, level, category, weeks, description, modules):
    return {"id": id, "title": title, "level": level, "category": category, "duration": weeks, "description": description, "builtin": True,
            "modules": [{"title": m, "lessons": [{"title": l, "minutes": mins} for l, mins in ls]} for m, ls in modules]}


